// Curated starter set of common whole foods and staples, in Spanish, all
// values per 100g of the raw/typical form unless noted in the name, plus a
// second block of real packaged/branded products (many Mercadona-brand
// "Hacendado") pulled one-off from Open Food Facts — see below. Synced into
// the local database on every launch by food_seeder.dart (only entries
// missing by name are inserted) — the app never depends on this list, or on
// any network call, at runtime otherwise. Users extend it freely via
// "Crear alimento personalizado" (isCustom = true on those rows).
//
// The branded block's data is sourced from Open Food Facts
// (https://openfoodfacts.org), a collaborative database licensed under the
// Open Database License (ODbL) — reproduced here per its attribution
// requirement. It was a one-time import (countries=Spain, lang=es, sorted by
// scan popularity, filtered to entries with complete macros), not a live
// dependency; re-importing means re-running the same process by hand, there
// is no sync script.
class FoodSeed {
  const FoodSeed({
    required this.category,
    required this.name,
    required this.kcalPer100g,
    required this.proteinPer100g,
    required this.carbsPer100g,
    required this.fatPer100g,
    this.fiberPer100g,
    this.defaultServingGrams,
    this.servingLabel,
  });

  final FoodCategory category;
  final String name;
  final double kcalPer100g;
  final double proteinPer100g;
  final double carbsPer100g;
  final double fatPer100g;
  final double? fiberPer100g;
  final double? defaultServingGrams;
  final String? servingLabel;
}

